import{_ as o,l,o as e,c as s,v as r,p as n,x as i,d as h,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"镜面形状误差","description":"","frontmatter":{"title":"镜面形状误差","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mirror-figure-error.md","filePath":"litho/mirror-figure-error.md","lastUpdated":1789023840000}'),E={name:"litho/mirror-figure-error.md"};function u(c,a,m,f,B,A){const t=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="镜面形状误差" tabindex="-1">镜面形状误差 <a class="header-anchor" href="#镜面形状误差" aria-label="Permalink to &quot;镜面形状误差&quot;">​</a></h1><div class="epigraph"><p>低频面形是镜子「长得不像设计的那张二次曲面」。它改波前和场曲，不改 TIS 那一桶，但 High-NA 的公差以皮米计。</p><footer>—— 对照 Zeiss 对 EUV 投影光学面形与波前的公开要求；Bakshi 系统光学</footer></div><p><a href="/litho/multilayer-roughness-scatter">上一课</a>把高度谱的中高频写成散射。缺口是低频端：形状误差（figure error）。蔡司装调盯的首先是这张面：投影六镜把亚纳米波前乘进空中像，像差进 Zernike，不进 flare 核。中频那一段专门有名字，留给<a href="/litho/msfr">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>散射课用 PSD 分段。低频对应空间波长从镜子口径量级到大约毫米以上，用面形干涉仪或可见光/EUV 波前传感器看。误差表现为离焦、像散、彗差和更高等，跨场扫描时变成 CD 与套刻指纹。EUV 全反射、无透镜补偿，每一面的面形都直接进投影波前；NA 从 0.33 到 0.55，对同一波前误差的瑞利容忍更紧。</p><p>缺口是把 figure 从「抛光得好不好」落到成像预算，而不是再写一遍 TIS 公式。热漂移也是面形：瓦级吸收让基底膨胀，运行中的 figure 不等于出厂图——<a href="/litho/lens-heating-compensation">镜头热补偿</a> 的 EUV 版发生在真空反射镜上。</p><p><span class="marginnote">面形合格、MSFR 超标：像差好看、对比差。反过来：晕斑小、场曲大。分频就是为了不让一个 RMS 掩盖两种病。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>出厂：干涉测量面形，减设计面，残差进 Zernike 或自由面系数。镀多层之后还要再测——膜应力会把 figure 拉弯，必须在镀膜应力和基底刚度之间预补偿。装调：六镜（High-NA 更多或变形组）用刚体自由度把系统波前收到规格，补偿不了的高阶留给单镜返工。</p><p>运行：功率、氢和污染改变局部吸收，面形慢漂。传感器用衍射或刻蚀标记看像差，执行器是镜体位移/倾斜，行程有限。收集镜的椭球面形同样有 figure 项，但它首先改 IF 共轭和光瞳均匀，投影镜才直接改硅片空中像。</p><h3 id="镀膜应力是出厂面形的一部分" tabindex="-1">镀膜应力是出厂面形的一部分 <a class="header-anchor" href="#镀膜应力是出厂面形的一部分" aria-label="Permalink to &quot;镀膜应力是出厂面形的一部分&quot;">​</a></h3><p>多层有压应力。镀完若不预补偿，刚体面形会弯出像散和更高阶。离子束修形可以在镀前把基底修成「镀完才对」的反变形。运行中氢和热再改应力，预补偿不是一次完工。后课 MSFR 不管这些低频弯，装调也补偿不了中频纹。</p>',12)),(e(),n(d,null,{default:i(()=>[p(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20FIG%5B%22%E4%BD%8E%E9%A2%91%E9%9D%A2%E5%BD%A2%E6%AE%8B%E5%B7%AE%22%5D%20--%3E%20WF%5B%22%E7%B3%BB%E7%BB%9F%E6%B3%A2%E5%89%8D%22%5D%0A%20%20WF%20--%3E%20Z%5B%22Zernike%20%E5%83%8F%E5%B7%AE%22%5D%0A%20%20HEAT%5B%22%E5%90%B8%E6%94%B6%E7%83%AD%E5%8F%98%E5%BD%A2%22%5D%20--%3E%20FIG%0A%20%20STRESS%5B%22%E9%95%80%E8%86%9C%E5%BA%94%E5%8A%9B%22%5D%20--%3E%20FIG%0A%20%20Z%20--%3E%20CD%5B%22%E8%B7%A8%E5%9C%BA%20CD%20%2F%20%E5%A5%97%E5%88%BB%E6%8C%87%E7%BA%B9%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>波前误差 \\(\\Delta W \\approx 2\\,\\Delta z\\cos\\theta\\) 量级（反射），高度误差被双程放大。13.5 nm 的 \\(2\\pi\\) 相位对应的高度只有数纳米；分配到六面、再扣掉可补偿的刚体项，单镜公差落到皮米–亚纳米。这是 Zerodur 或同等超低膨胀基底、离子束修形的理由。像差进 TCC，NILS 和焦深一起掉；与散射不同，OPC 的 flare 核修不了彗差造成的左右不对称。</p><p><span class="marginnote">Zeiss 公开把 EUV 光学说成原子量级面形合同。不要把可见光镜头的 λ/20 习惯直接换算到 13.5 nm——双程反射和短波把数字再削一截。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把中频的「小角度散射 vs 像差」灰色地带写完，那正是下一课 MSFR。不写掩模坯的面形——掩模厂另课。运行热面形与出厂干涉图要分开管，不能用一张补偿表打天下。出处：Zeiss EUV optics；Bakshi 投影光学；ASML 对波前与像差控制的公开讨论。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Figure 是低频形状误差，进波前与像差，不进 TIS 桶。</li><li>镀膜应力和热负荷让运行面形偏离出厂；补偿行程有限。</li><li>下一课专攻夹在面形与高频抛光之间的 MSFR。</li><li>出处：Zeiss；Bakshi；ASML 波前公开材料。</li></ul>',7))])}const D=o(E,[["render",u]]);export{S as __pageData,D as default};
